'use strict';
const $=id=>document.getElementById(id),C=VaultCore,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db=null,record=null,session=null,busy=false,view='all',category='',editing=null,lastActivity=Date.now(),confirmTask=null;
const states={active:'Đang sử dụng',building:'Đang xây dựng',paused:'Tạm dừng'};
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('an-web-vault-updates'):null;
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',5000)}
function busyUI(value){busy=value;document.querySelectorAll('button').forEach(b=>b.disabled=value);$('saveState').textContent=value?'◌ Đang mã hóa và lưu…':'● Đã mã hóa trên thiết bị'}
async function task(fn,errorId){if(busy)return;busyUI(true);if(errorId)$(errorId).textContent='';try{await fn()}catch(e){const message=e.code==='CONFLICT'?'Kho đã thay đổi ở tab khác. Mở khóa lại để lấy bản mới.':e.name==='QuotaExceededError'?'Thiết bị đã hết dung lượng lưu. Hãy xuất bản sao trước khi dọn dữ liệu.':e.message||'Chưa thực hiện được. Vui lòng thử lại.';if(e.code==='CONFLICT')hardLock();if(errorId)$(errorId).textContent=message;else toast(message)}finally{busyUI(false)}}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('an-private-websites',1);req.onupgradeneeded=()=>req.result.createObjectStore('vault');req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result)};req.onerror=()=>reject(Error('Trình duyệt chưa cho phép lưu dữ liệu. Thử cửa sổ thường hoặc kiểm tra quyền lưu trữ.'));req.onblocked=()=>reject(Error('Đóng các tab cũ của website rồi mở lại.'))})}
function readRecord(){return new Promise((resolve,reject)=>{const tx=db.transaction('vault','readonly'),req=tx.objectStore('vault').get('main');req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)})}
function writeRecord(next,expected){return new Promise((resolve,reject)=>{let conflict=false;const tx=db.transaction('vault','readwrite'),store=tx.objectStore('vault'),req=store.get('main');req.onsuccess=()=>{const revision=req.result?.revision||0;if(revision!==expected){conflict=true;tx.abort();return}store.put(next,'main')};tx.oncomplete=()=>resolve();tx.onabort=tx.onerror=()=>{const e=Error(conflict?'Dữ liệu đã đổi ở tab khác.':'Không lưu được dữ liệu trên thiết bị.');e.code=conflict?'CONFLICT':undefined;if(tx.error?.name==='QuotaExceededError')e.name='QuotaExceededError';reject(e)}})}
async function commit(data,key=session.key,salt=session.salt,iterations=session.iterations){const encrypted=await C.seal(data,key,salt,iterations),next={revision:record.revision+1,envelope:encrypted};await writeRecord(next,record.revision);record=next;session={data,key,salt,iterations};channel?.postMessage({revision:next.revision});render()}
async function mutate(fn){const next=structuredClone(session.data);fn(next);C.validData(next);await commit(next)}
function gate(){const exists=!!record;$('gatePass').type='password';document.querySelectorAll('[data-show]').forEach(b=>b.textContent='Hiện');$('gateTitle').textContent=exists?'Chào bạn quay lại.':'Tạo chiếc kho đầu tiên';$('gateIntro').textContent=exists?'Nhập mật khẩu của bạn để mở kho website trên thiết bị này.':'Tự đặt mật khẩu để bảo vệ danh sách website của bạn.';$('gateSubmit').textContent=exists?'Mở kho của tôi ↗':'Tạo kho của tôi ↗';$('confirmLabel').hidden=exists;$('gateConfirm').required=!exists;$('gatePass').autocomplete=exists?'current-password':'new-password';$('gateImport').hidden=exists;$('gatePass').value='';$('gateConfirm').value='';$('gateError').textContent='';$('gate').hidden=false;$('app').hidden=true}
function showApp(){lastActivity=Date.now();$('gateForm').reset();$('gate').hidden=true;$('app').hidden=false;view='all';category='';$('search').value='';render()}
function hardLock(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.querySelectorAll('input[type=password]').forEach(i=>i.value='');session=null;editing=null;confirmTask=null;$('cards').innerHTML='';$('categories').innerHTML='';$('categoryOptions').innerHTML='';$('crumb').textContent='Tất cả website';$('viewTitle').textContent='Tất cả website';$('confirmText').textContent='';$('bulkCategory').value='';$('resultsNote').textContent='';for(const id of ['statAll','statFav','statCats','navAll','navFav','navTrash'])$(id).textContent='0';$('editForm').reset();$('bulkText').value='';$('importForm').reset();$('search').value='';gate()}
function lock(){if(busy){toast('Đợi lưu xong rồi khóa kho nha.');return}hardLock();toast('Đã khóa kho.')}
$('gateForm').onsubmit=e=>{e.preventDefault();const pass=$('gatePass').value,confirm=$('gateConfirm').value;task(async()=>{record=await readRecord();if(record){session=await C.unlock(record.envelope,pass)}else{if(pass!==confirm)throw Error('Hai lần nhập mật khẩu chưa khớp.');const data=C.fresh(),result=await C.create(data,pass),next={revision:1,envelope:result.envelope};await writeRecord(next,0);record=next;session={data,key:result.key,salt:result.salt,iterations:result.iterations};channel?.postMessage({revision:1})}showApp()},'gateError')};
function filtered(){const query=C.fold($('search').value.trim()),status=$('statusFilter').value;let list=session.data.entries.filter(e=>view==='trash'?!!e.deleted:!e.deleted);if(view==='favorites')list=list.filter(e=>e.favorite);if(view==='recent')list=list.filter(e=>e.opened);if(view==='category')list=list.filter(e=>e.category===category);if(query)list=list.filter(e=>C.fold([e.title,e.url,e.category,e.notes,...e.tags].join(' ')).includes(query));if(status!=='all')list=list.filter(e=>e.status===status);const sort=$('sort').value;return list.sort((a,b)=>view==='recent'?String(b.opened).localeCompare(String(a.opened)):sort==='name'?a.title.localeCompare(b.title,'vi'):sort==='old'?a.created.localeCompare(b.created):sort==='updated'?b.updated.localeCompare(a.updated):b.created.localeCompare(a.created))}
function render(){if(!session)return;const data=session.data,active=data.entries.filter(e=>!e.deleted),groups=[...new Set(active.map(e=>e.category))].sort((a,b)=>a.localeCompare(b,'vi'));for(const id of ['statAll','navAll'])$(id).textContent=active.length;for(const id of ['statFav','navFav'])$(id).textContent=active.filter(e=>e.favorite).length;$('statCats').textContent=groups.length;$('navTrash').textContent=data.entries.filter(e=>e.deleted).length;$('categories').innerHTML=groups.map(g=>`<button class="navitem categoryitem ${view==='category'&&category===g?'active':''}" data-category="${esc(g)}"><span>●</span> ${esc(g)}</button>`).join('');$('categoryOptions').innerHTML=groups.map(g=>`<option value="${esc(g)}"></option>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const title=view==='category'?category:({all:'Tất cả website',favorites:'Website yêu thích',recent:'Website vừa mở',trash:'Thùng rác'}[view]);$('viewTitle').innerHTML=esc(title)+' <span id="viewCount"></span>';$('crumb').textContent=title;const list=filtered();$('viewCount').textContent=list.length;$('emptyTrash').hidden=view!=='trash'||!data.entries.some(e=>e.deleted);$('viewHint').textContent=view==='trash'?'Website đã xóa vẫn ở đây cho đến khi bạn xóa vĩnh viễn.':'Những dự án của bạn, được giữ lại cẩn thận.';$('cards').innerHTML=list.map(e=>{const domain=new URL(e.url).hostname;return`<article class="sitecard"><div class="cardart ${esc(e.color)}"><span class="cardmonogram">${esc(e.title.slice(0,2).toUpperCase())}</span>${!e.deleted?`<button class="favorite ${e.favorite?'on':''}" data-action="favorite" data-id="${esc(e.id)}" aria-label="${e.favorite?'Bỏ':'Đánh dấu'} yêu thích">${e.favorite?'★':'☆'}</button>`:''}</div><div class="cardbody"><div class="cardtop"><h3>${esc(e.title)}</h3>${!e.deleted?`<button class="edit" data-action="edit" data-id="${esc(e.id)}" aria-label="Sửa website">⋯</button>`:''}</div><span class="domain" title="${esc(e.url)}">${esc(domain)}</span><p class="cardnotes">${esc(e.notes||'Chưa thêm ghi chú cho website này.')}</p><div class="tags"><span class="tag">${esc(e.category)}</span>${e.tags.slice(0,3).map(t=>`<span class="tag">#${esc(t)}</span>`).join('')}</div><div class="cardfoot">${e.deleted?`<button class="open" data-action="restore" data-id="${esc(e.id)}">↶ Khôi phục</button><button class="danger" data-action="remove" data-id="${esc(e.id)}">Xóa vĩnh viễn</button>`:`<span class="statuspill ${e.status}">${states[e.status]}</span><div class="cardbuttons"><button data-action="copy" data-id="${esc(e.id)}" title="Sao chép link">⧉</button><button data-action="trash" data-id="${esc(e.id)}" title="Chuyển vào thùng rác">♲</button>${e.repo?`<button data-action="repo" data-id="${esc(e.id)}" title="Mở mã nguồn / quản trị">⌘</button>`:''}<button class="open" data-action="open" data-id="${esc(e.id)}">Mở ↗</button></div>`}</div></div></article>`}).join('');$('empty').hidden=list.length>0;if(!list.length){$('empty').querySelector('h3').textContent=active.length||view!=='all'?'Chưa có website trong mục này':'Chỗ cho ý tưởng đầu tiên của bạn';$('empty').querySelector('p').textContent=view==='trash'?'Các website bạn chuyển vào thùng rác sẽ xuất hiện tại đây.':$('search').value?'Thử từ khóa khác hoặc thay bộ lọc.':'Dán link website bạn đã tạo để bắt đầu bộ sưu tập.';$('emptyAdd').hidden=view==='trash'}$('resultsNote').textContent=`${list.length} website trong mục này · Không đặt hạn mức số lần lưu`;$('idleLabel').textContent=`Tự khóa sau ${data.settings.idleMinutes} phút`;$('idleSelect').value=data.settings.idleMinutes}
function setView(next,group=''){if(!session||busy)return;view=next;category=group;$('search').value='';$('statusFilter').value='all';render()}
$('mainNav').onclick=e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)};$('trashNav').onclick=()=>setView('trash');$('categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b)setView('category',b.dataset.category)};for(const id of ['search','statusFilter','sort'])$(id).addEventListener(id==='search'?'input':'change',()=>{if(session)render()});$('gridBtn').onclick=()=>{$('cards').classList.remove('list');$('gridBtn').classList.add('selected');$('listBtn').classList.remove('selected')};$('listBtn').onclick=()=>{$('cards').classList.add('list');$('listBtn').classList.add('selected');$('gridBtn').classList.remove('selected')};
function edit(id){if(!session||busy)return;editing=id||null;const e=id?session.data.entries.find(e=>e.id===id):null;$('editForm').reset();$('editError').textContent='';$('editTitle').textContent=e?'Sửa website của bạn':'Một website mới';for(const [input,key] of [['siteURL','url'],['siteName','title'],['siteCategory','category'],['siteStatus','status'],['siteNotes','notes'],['siteRepo','repo'],['siteColor','color']])$(input).value=e?.[key]||({siteStatus:'active',siteColor:'blue',siteCategory:view==='category'?category:''}[input]||'');$('siteTags').value=e?.tags.join(', ')||'';$('siteFavorite').checked=!!e?.favorite;$('editDialog').showModal();$('siteURL').focus()}
for(const id of ['addBtn','emptyAdd'])$(id).onclick=()=>edit();$('editForm').onsubmit=e=>{e.preventDefault();const input={url:$('siteURL').value,title:$('siteName').value,category:$('siteCategory').value,status:$('siteStatus').value,notes:$('siteNotes').value,tags:$('siteTags').value,repo:$('siteRepo').value,color:$('siteColor').value,favorite:$('siteFavorite').checked},id=editing;task(async()=>{await mutate(d=>C.add(d,input,id));$('editDialog').close();toast(id?'Đã lưu thay đổi.':'Đã thêm website vào kho.')},'editError')};
function confirm(title,text,fn){confirmTask=fn;$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmDialog').showModal()}
$('confirmAction').onclick=()=>{const fn=confirmTask;task(async()=>{await fn();$('confirmDialog').close();confirmTask=null})};
$('cards').onclick=e=>{const b=e.target.closest('[data-action]');if(!b||!session||busy)return;const value=session.data.entries.find(x=>x.id===b.dataset.id);if(!value)return;const action=b.dataset.action;if(action==='edit'){edit(value.id);return}if(action==='copy'){if(navigator.clipboard)navigator.clipboard.writeText(value.url).then(()=>toast('Đã sao chép đường link.'),()=>toast('Chưa sao chép được. Mở Sửa để lấy đường link.'));else toast('Trình duyệt chưa hỗ trợ sao chép. Mở Sửa để lấy đường link.');return}if(action==='repo'){window.open(value.repo,'_blank','noopener,noreferrer');return}if(action==='open'){window.open(value.url,'_blank','noopener,noreferrer');task(()=>mutate(d=>{d.entries.find(x=>x.id===value.id).opened=new Date().toISOString()}));return}if(action==='remove'){confirm('Xóa vĩnh viễn website?',`“${value.title}” sẽ bị xóa khỏi kho trên thiết bị này.`,async()=>{await mutate(d=>{d.entries=d.entries.filter(x=>x.id!==value.id)});toast('Đã xóa vĩnh viễn.')});return}task(async()=>{await mutate(d=>{const v=d.entries.find(x=>x.id===value.id);if(action==='favorite')v.favorite=!v.favorite;if(action==='trash')v.deleted=new Date().toISOString();if(action==='restore')v.deleted=null;v.updated=new Date().toISOString()});if(action==='trash')toast('Đã chuyển vào thùng rác. Bạn có thể khôi phục.');if(action==='restore')toast('Đã khôi phục website.')})};
$('emptyTrash').onclick=()=>confirm('Dọn sạch thùng rác?','Tất cả website trong thùng rác sẽ bị xóa vĩnh viễn khỏi kho hiện tại.',async()=>{await mutate(d=>{d.entries=d.entries.filter(e=>!e.deleted)});toast('Đã dọn thùng rác.')});
$('bulkBtn').onclick=()=>{$('bulkText').value='';$('bulkCategory').value=view==='category'?category:'';$('bulkError').textContent='';$('bulkDialog').showModal()};$('bulkSave').onclick=()=>{const raw=$('bulkText').value,group=$('bulkCategory').value;task(async()=>{const lines=raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)throw Error('Dán ít nhất một đường link.');const parsed=lines.map((line,i)=>{const parts=line.split('|');try{return{url:C.url(parts.length>1?parts.slice(1).join('|'):line),title:parts.length>1?parts[0].trim():'',category:group}}catch(err){throw Error(`Dòng ${i+1}: ${err.message}`)}});let added=0;await mutate(d=>{for(const input of parsed){if(d.entries.some(e=>C.canonical(e.url)===C.canonical(input.url)))continue;C.add(d,input);added++}});$('bulkDialog').close();toast(`Đã lưu ${added} website; bỏ qua ${parsed.length-added} link trùng.`)},'bulkError')};
function download(data,name){const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('settingsBtn').onclick=()=>{if(session){$('storageNote').textContent='';$('settingsDialog').showModal()}};$('idleSelect').onchange=()=>{const minutes=+$('idleSelect').value;task(async()=>{await mutate(d=>d.settings.idleMinutes=minutes);toast('Đã đổi thời gian tự khóa.')})};$('backupBtn').onclick=()=>{if(session&&!busy){download(JSON.stringify(record.envelope),'kho-website-ma-hoa-'+new Date().toISOString().slice(0,10)+'.json');toast('Đã xuất bản sao mã hóa. Giữ lại mật khẩu hiện tại để mở file này.')}};
$('changePassBtn').onclick=()=>{$('passwordForm').reset();$('passwordError').textContent='';$('passwordDialog').showModal()};$('passwordForm').onsubmit=e=>{e.preventDefault();const old=$('oldPass').value,next=$('newPass').value,confirmation=$('newConfirm').value;task(async()=>{if(next!==confirmation)throw Error('Hai lần nhập mật khẩu mới chưa khớp.');await C.unlock(record.envelope,old);const created=await C.create(session.data,next);await commit(session.data,created.key,created.salt,created.iterations);$('passwordDialog').close();$('passwordForm').reset();toast('Đã đổi mật khẩu. Các bản sao cũ vẫn dùng mật khẩu cũ.')},'passwordError')};
function openImport(){if(!session&&record){toast('Mở khóa kho hiện tại trước khi nhập bản sao.');return}$('importForm').reset();$('importError').textContent='';$('importHint').textContent=session?'Chỉ thêm website chưa có. Link trùng giữ nguyên; mật khẩu kho hiện tại không đổi.':'Khôi phục kho từ file mã hóa. Mật khẩu của bản sao sẽ là mật khẩu kho này.';$('importDialog').showModal()}
$('importBtn').onclick=openImport;$('gateImport').onclick=openImport;$('importForm').onsubmit=e=>{e.preventDefault();const file=$('importFile').files[0],password=$('importPass').value;task(async()=>{if(!file)throw Error('Chọn file sao lưu JSON.');if(file.size>50*1024*1024)throw Error('File nhập vượt 50 MB. Hãy kiểm tra lại đúng bản sao kho.');let encrypted;try{encrypted=JSON.parse(await file.text())}catch{throw Error('File JSON không đọc được.')}const opened=await C.unlock(encrypted,password);if(session){const merged=C.merge(session.data,opened.data);await commit(merged.data);toast(`Đã nhập ${merged.added} website; bỏ qua ${merged.skipped} link trùng.`)}else{const latest=await readRecord();if(latest){record=latest;throw Error('Thiết bị này vừa có kho mới. Đóng cửa sổ này rồi mở khóa kho.')}const next={revision:1,envelope:encrypted};await writeRecord(next,0);record=next;session=opened;channel?.postMessage({revision:1});showApp();toast('Đã khôi phục kho trên thiết bị này.')} $('importDialog').close();$('importForm').reset()},'importError')};
$('persistBtn').onclick=()=>task(async()=>{if(!navigator.storage?.persist){$('storageNote').textContent='Trình duyệt này chưa hỗ trợ yêu cầu lưu lâu dài. Hãy xuất bản sao định kỳ.';return}const ok=await navigator.storage.persist();$('storageNote').textContent=ok?'Trình duyệt đã cấp quyền lưu lâu dài. Bạn vẫn nên giữ bản sao riêng.':'Trình duyệt chưa cấp quyền. Dữ liệu hiện tại vẫn được lưu; hãy giữ bản sao định kỳ.'});
$('lockBtn').onclick=$('topLock').onclick=lock;document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close&&!busy){const d=$(close.dataset.close);d.close();d.querySelectorAll('input[type=password]').forEach(i=>i.value='')}const show=e.target.closest('[data-show]');if(show){const input=$(show.dataset.show);input.type=input.type==='password'?'text':'password';show.textContent=input.type==='password'?'Hiện':'Ẩn'}});for(const event of ['pointerdown','keydown','touchstart'])document.addEventListener(event,()=>{lastActivity=Date.now()},{passive:true});setInterval(()=>{if(session&&!busy&&Date.now()-lastActivity>session.data.settings.idleMinutes*60000){hardLock();toast('Kho đã tự khóa vì không thao tác.')}},15000);if(channel)channel.onmessage=e=>{if(session&&e.data?.revision!==record?.revision){hardLock();toast('Kho vừa thay đổi ở tab khác. Mở khóa lại để lấy dữ liệu mới.')}};
$('gateSubmit').disabled=true;$('gateImport').disabled=true;
(async()=>{try{if(!window.crypto?.subtle)throw Error('Cần trình duyệt hỗ trợ mã hóa và kết nối HTTPS (hoặc localhost).');db=await openDB();record=await readRecord();gate();$('gateSubmit').disabled=false;$('gateImport').disabled=false}catch(e){$('gateError').textContent=e.message;$('gateSubmit').disabled=true;$('gateImport').disabled=true}})();
